/* User-supplied childbirth notes, evaluated as traditional rule conditions only. */
(function(root){'use strict';
const names={Su:['Sun','रवी'],Mo:['Moon','चंद्र'],Ma:['Mars','मंगळ'],Me:['Mercury','बुध'],Ju:['Jupiter','गुरु'],Ve:['Venus','शुक्र'],Sa:['Saturn','शनि'],Ra:['Rahu','राहू'],Ke:['Ketu','केतू']};
const rules=[
 {id:'both-barren',b:[true,true],groups:[[1,4,10],[6,8,12],[2,5,11]],en:'The supplied table associates this combination with adoption or surrogacy; this does not determine fertility.',mr:'दिलेल्या तक्त्यात या संयोगाचा संबंध दत्तक किंवा सरोगसीशी जोडला आहे; यावरून प्रजननक्षमता ठरत नाही.'},
 {id:'star-barren',b:[false,true],groups:[[2,5,11,4,8,10],[2,5,11,6,8,12]],en:'The supplied table mentions treatment / IVF. A medical assessment is required; the chart cannot establish a need for IVF.',mr:'दिलेल्या तक्त्यात उपचार किंवा कृत्रिम गर्भधारणेचा उल्लेख आहे. त्याची गरज वैद्यकीय तपासणीनेच ठरते.'},
 {id:'csl-barren',b:[true,false],groups:[[2,5,11],[4,6,8,12]],en:'The supplied table mentions treatment. It also gives an overlapping adoption / pregnancy-loss interpretation for this same combination, so no single outcome is selected.',mr:'दिलेल्या तक्त्यात उपचाराचा उल्लेख आहे. याच संयोगासाठी दत्तक किंवा गर्भहानीचा वेगळा अर्थही दिला असल्याने एकच निष्कर्ष निवडलेला नाही.'},
 {id:'both-mars',pair:['Ma','Ma'],en:'Both lords are Mars. The supplied adverse child-survival statement cannot establish a medical outcome.',mr:'दोन्ही स्वामी मंगळ आहेत. दिलेल्या प्रतिकूल बालजीवनविषयक विधानावरून वैद्यकीय निष्कर्ष ठरत नाही.'},
 {id:'ketu',ketu:true,en:'A Ketu connection is present. The supplied one-child statement is retained as a traditional reference; it cannot determine family size.',mr:'केतूचा संबंध आहे. दिलेले एक-संततीविषयक विधान पारंपरिक संदर्भ आहे; यावरून कुटुंबातील मुलांची संख्या ठरत नाही.'},
 {id:'mars-negative',star:'Ma',groups:[[1,4,10]],en:'Mars star lord with adverse-house support: the supplied notes mention complications. No surgery, loss, survival or percentage is predicted.',mr:'मंगळ नक्षत्रस्वामी व प्रतिकूल भावांचा संबंध: दिलेल्या नोंदीत अडचणींचा उल्लेख आहे. शस्त्रक्रिया, गर्भहानी, बालजीवन किंवा टक्केवारीचे भाकीत केलेले नाही.'}
];
function analyze(model,cusp=5){
 if(!model?.ready)return {ready:false,rows:[],reason:'Complete the natal chart to see predictions.'};
 const c=model.houses?.find(h=>h.id===Number(cusp)),lord=model.planets?.find(p=>p.id===c?.sl),star=model.planets?.find(p=>p.id===lord?.stl);
 if(!lord||!star||![lord,star].every(p=>Number.isInteger(p.signIndex)&&p.signIndex>=0&&p.signIndex<12)||![5,7,9].includes(Number(cusp)))return {ready:false,rows:[],reason:'The selected child cusp and its lords are required.'};
 const lang=root.KPPreferences?.get?.().language||'english',mr=lang==='marathi',bi=lang==='bilingual',say=(en,ma)=>bi?en+'\n'+ma:mr?ma:en;
 const rows=[],add=(id,en,ma)=>rows.push({id:'childbirth-'+id,language:mr?'marathi':'english',title:say('Traditional childbirth rule review','पारंपरिक संतती नियम परीक्षण'),text:say(en,ma),status:'review'});
 const housesFor=id=>{const r=model.fourfold?.planets?.find(p=>p.id===id);return [...new Set(['A','B','C','D'].flatMap(k=>r?.[k]||[]))];};
 const houses=[...new Set([...housesFor(lord.id),...housesFor(star.id)])],barren=p=>[0,2,4,5].includes(p.signIndex),matched=[];
 add('basis','Cusp '+cusp+'; cusp sub lord: '+names[lord.id][0]+'; its star lord: '+names[star.id][0]+'. Combined four-fold houses: '+(houses.join(', ')||'none')+'. Barren-sign convention: Aries, Gemini, Leo, Virgo. NK is interpreted as the star lord of the cusp sub lord.','भाव '+cusp+'; भाव उपस्वामी: '+names[lord.id][1]+'; त्याचा नक्षत्रस्वामी: '+names[star.id][1]+'. संयुक्त चार-पदरी कार्येश भाव: '+(houses.join(', ')||'नाही')+'. वंध्य राशी संकेत: मेष, मिथुन, सिंह, कन्या. नक्षत्रस्वामी म्हणजे भाव उपस्वामीचा नक्षत्रस्वामी मानला आहे.');
 const positive=[2,5,11].filter(h=>houses.includes(h)),negative=[1,4,10].filter(h=>houses.includes(h));
 add('house-support','Positive houses (2, 5, 11): '+(positive.join(', ')||'none')+'. Negative houses (1, 4, 10): '+(negative.join(', ')||'none')+'. '+(negative.length&&!positive.length?'Only negative-house support is present. Your rule associates this with sterility / no child; this is not a diagnosis of infertility.':positive.length&&negative.length?'Both positive and negative support are present; do not treat the result as a definite yes or no.':positive.length?'Positive childbirth-house support is present; pregnancy is not medically confirmed.':'Neither group has support; no conclusion.'),'अनुकूल भाव (२, ५, ११): '+(positive.join(', ')||'नाही')+'. प्रतिकूल भाव (१, ४, १०): '+(negative.join(', ')||'नाही')+'. '+(negative.length&&!positive.length?'केवळ प्रतिकूल भावांचा संबंध आहे. आपल्या नियमानुसार हा वंध्यत्व किंवा संतती नसण्याचा पारंपरिक संकेत आहे; हे वंध्यत्वाचे वैद्यकीय निदान नाही.':positive.length&&negative.length?'अनुकूल व प्रतिकूल दोन्ही संबंध असल्याने निश्चित होकार किंवा नकार दिलेला नाही.':positive.length?'संततीविषयक अनुकूल भावांचा संबंध आहे; यावरून गर्भधारणा वैद्यकीयदृष्ट्या निश्चित होत नाही.':'दोन्ही गटांचा संबंध नसल्याने निष्कर्ष नाही.'));
 for(const r of rules){if(r.b&&(barren(lord)!==r.b[0]||barren(star)!==r.b[1]))continue;if(r.pair&&(lord.id!==r.pair[0]||star.id!==r.pair[1]))continue;if(r.ketu&&lord.id!=='Ke'&&star.id!=='Ke')continue;if(r.star&&star.id!==r.star)continue;if(r.groups&&!r.groups.some(g=>g.every(h=>houses.includes(h))))continue;matched.push(r.id);add(r.id,r.en,r.mr);}
 if(!matched.length)add('no-match','No unambiguous condition in the supplied childbirth table fully matches this selection.','दिलेल्या संतती तक्त्यातील स्पष्ट अट या निवडीशी पूर्ण जुळत नाही.');
 const horary=root.document?.getElementById('chart-kind')?.value==='horary'||root.document?.getElementById('instant-prashna')?.value==='1';
 if(horary){const group=['Ke','Mo','Su','Ju'].includes(lord.id)?0:['Me','Ve'].includes(lord.id)?1:2;add('delivery',['Horary delivery reference: on-time category.','Horary delivery reference: premature category.','Horary delivery reference: delayed category.'][group]+' This is not an estimated medical delivery date.',['प्रश्नकुंडलीतील प्रसूती संदर्भ: वेळेवर गट.','प्रश्नकुंडलीतील प्रसूती संदर्भ: मुदतपूर्व गट.','प्रश्नकुंडलीतील प्रसूती संदर्भ: विलंब गट.'][group]+' हा वैद्यकीय प्रसूतीदिनाचा अंदाज नाही.');}
 add('review','The notes also contain ambiguous pregnancy-month, child-sex and twin-outcome formulas. These are retained in the supplied-rule reference, not asserted as calculated medical facts.','नोंदीतील गर्भावधी, बाललिंग व जुळ्या संततीचे निष्कर्ष देणाऱ्या अटी संदिग्ध आहेत. त्या दिलेल्या नियमांच्या संदर्भात ठेवल्या आहेत; वैद्यकीय तथ्य म्हणून गणिती निष्कर्ष दिलेले नाहीत.');
 return {ready:true,rows,cusp:Number(cusp),matched,houseSystem:'existing-kp-fourfold',houses,positive,negative,lord:lord.id,star:star.id};
}
root.KPChildbirth=Object.freeze({analyze,rules});if(typeof module!=='undefined'&&module.exports)module.exports=root.KPChildbirth;
})(typeof window==='undefined'?globalThis:window);
